#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    string num;
    cin >> n >> num;

    int firstSum = 0, secondSum = 0;

    for (int i = 0; i < n; ++i) {
        if (num[i] != '4' && num[i] != '7') {
            cout << "NO\n";
            return 0;
        }

        if (i < n / 2)
            firstSum += num[i] - '0';
        else
            secondSum += num[i] - '0';
    }

    cout << (firstSum == secondSum ? "YES\n" : "NO\n");
    return 0;
}

